# Define the function signature for gsl_stats_median_from_sorted_data
gsl.gsl_stats_median_from_sorted_data.argtypes = [
    ctypes.POINTER(ctypes.c_double),  # data
    ctypes.c_size_t,                  # stride
    ctypes.c_size_t                   # n
]
gsl.gsl_stats_median_from_sorted_data.restype = ctypes.c_double

def compute_median(sorted_data, stride, n):
    """
    Computes the median of a sorted list using GSL's function via ctypes.
    Parameters:
        sorted_data (list): A sorted list of double-precision floating-point numbers.
        stride (int): The stride between elements in the array.
        n (int): Number of elements in the array.
    Returns:
        float: The computed median.
    Raises:
        ValueError: If inputs are invalid or if the list is empty.
    """
    if not isinstance(sorted_data, list) or not all(isinstance(x, (float, int)) for x in sorted_data):
        raise ValueError("Input 'sorted_data' must be a list of numbers.")
    if not isinstance(stride, int) or stride <= 0:
        raise ValueError("Stride must be a positive integer.")
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Number of elements must be a positive integer.")
    if len(sorted_data) < n:
        raise ValueError("The length of 'sorted_data' must be at least 'n'.")

    # Convert the Python list to a C-compatible array of doubles
    c_array = (ctypes.c_double * n)()
    for i in range(n):
        c_array[i] = sorted_data[i * stride]

    # Call the GSL function to compute the median
    median = gsl.gsl_stats_median_from_sorted_data(c_array, ctypes.c_size_t(stride), ctypes.c_size_t(n))
    return float(median)

