import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()
        self._gsl_matrix = None

    def get_data(self):
        return np.ctypeslib.as_array(self.data, shape=(self.rows, self.cols))

    def set_data(self, data):
        if data.shape != (self.rows, self.cols):
            raise ValueError(f"Data shape {data.shape} does not match matrix dimensions ({self.rows}, {self.cols})")
        np.copyto(np.ctypeslib.as_array(self.data, shape=(self.rows, self.cols)), data)

    def free(self):
        if self._gsl_matrix:
            gsl.gsl_matrix_free(self._gsl_matrix)
            self._gsl_matrix = None

    def __del__(self):
        self.free()

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return libgsl
    except Exception as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

gsl = load_gsl_libraries()

def gsl_matrix_alloc(rows, cols):
    func = gsl.gsl_matrix_alloc
    func.argtypes = [ctypes.c_size_t, ctypes.c_size_t]
    func.restype = ctypes.POINTER(ctypes.c_void_p)
    return func(rows, cols)

def gsl_matrix_free(matrix):
    func = gsl.gsl_matrix_free
    func.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
    func(matrix)

def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray) or np_array.ndim != 2:
        raise ValueError("Input must be a 2D NumPy array.")

    rows, cols = np_array.shape
    gsl_matrix = GSLMatrix(rows, cols)
    gsl_matrix.set_data(np_array)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    return gsl_matrix.get_data().copy()

def gsl_multifit_covar(jacobian, epsrel):
    if not isinstance(jacobian, np.ndarray) or jacobian.ndim != 2:
        raise ValueError("Jacobian must be a 2D NumPy array.")

    rows, cols = jacobian.shape
    jac_gsl = numpy_to_gsl_matrix(jacobian)
    covar_gsl = GSLMatrix(cols, cols)

    func = gsl.gsl_multifit_covar
    func.argtypes = [
        ctypes.POINTER(ctypes.c_void_p),
        ctypes.c_int,
        ctypes.c_double,
        ctypes.POINTER(ctypes.c_void_p)
    ]
    func.restype = ctypes.c_int

    result = func(
        jac_gsl._gsl_matrix,
        ctypes.c_int(0),
        ctypes.c_double(epsrel),
        covar_gsl._gsl_matrix
    )

    if result != 0:
