        if not isinstance(np_array, np.ndarray) or np_array.dtype != np.complex128:
            raise ValueError("Input must be a NumPy array of complex numbers.")

        rows, cols = np_array.shape
        size_t = ctypes.c_size_t
        gsl_matrix_complex_p = ctypes.POINTER(ctypes.c_double * (2 * rows * cols))

        matrix = (ctypes.c_double * (2 * rows * cols))(*np_array.view(np.float64).flatten())
        return matrix, rows, cols

    def gsl_vector_to_numpy(self, gsl_vector, size):
        data = np.ctypeslib.as_array(gsl_vector, shape=(size,))
        return data.copy()

    def compute_eigenvalues(self, A, B):
        if A.shape != B.shape:
            raise ValueError("Matrices A and B must have the same dimensions.")
        if len(A.shape) != 2 or A.shape[0] != A.shape[1]:
            raise ValueError("Matrices A and B must be square.")

        A_data, A_rows, A_cols = self.numpy_to_gsl_matrix_complex(A)
        B_data, B_rows, B_cols = self.numpy_to_gsl_matrix_complex(B)

        if A_rows != B_rows or A_cols != B_cols:
            raise ValueError("Matrices A and B must have the same dimensions.")

        # Define function signatures for GSL functions
        self.gsl.gsl_eigen_genherm.argtypes = [
            ctypes.POINTER(ctypes.c_double * (2 * A_rows * A_cols)),
            ctypes.POINTER(ctypes.c_double * (2 * B_rows * B_cols)),
            ctypes.POINTER(ctypes.c_double * A_rows),
            ctypes.POINTER(ctypes.c_double * A_rows),
            ctypes.POINTER(ctypes.c_int)
        ]
        self.gsl.gsl_eigen_genherm.restype = ctypes.c_int

        eigenvalues = (ctypes.c_double * A_rows)()
        workspace = (ctypes.c_double * A_rows)()
        status = ctypes.c_int(0)

        result = self.gsl.gsl_eigen_genherm(
            A_data,
            B_data,
            eigenvalues,
            workspace,
            ctypes.byref(status)
        )

        if result != 0:
            raise RuntimeError(f"GSL error in eigenvalue computation: {result}")

        return self.gsl_vector_to_numpy(eigenvalues, A_rows)

