gsl = None

def load_gsl():
    global gsl
    try:
        # Load the required CBLAS library first with RTLD_GLOBAL to ensure symbols are visible
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
