# Define necessary types and functions from GSL

class gsl_complex(ctypes.Structure):
    _fields_ = [
        ("dat", ctypes.c_double * 2),  # real and imaginary parts
    ]

class gsl_vector(ctypes.Structure):
    pass

class gsl_matrix_complex(ctypes.Structure):
    pass

class gsl_eigen_hermv_workspace(ctypes.Structure):
    pass

gsl_matrix_complex_p = ctypes.POINTER(gsl_matrix_complex)
gsl_vector_p = ctypes.POINTER(gsl_vector)
gsl_eigen_hermv_workspace_p = ctypes.POINTER(gsl_eigen_hermv_workspace)

gsl_complex_p = ctypes.POINTER(gsl_complex)

def gsl_matrix_complex_alloc(rows, cols):
    return gsl.gsl_matrix_complex_alloc(rows, cols)

def gsl_matrix_complex_free(matrix):
    return gsl.gsl_matrix_complex_free(matrix)

def gsl_vector_alloc(size):
    return gsl.gsl_vector_alloc(size)

def gsl_vector_free(vector):
    return gsl.gsl_vector_free(vector)

def gsl_eigen_hermv_alloc(n):
    return gsl.gsl_eigen_hermv_alloc(n)

def gsl_eigen_hermv_free(workspace):
    return gsl.gsl_eigen_hermv_free(workspace)

def gsl_eigen_hermv(matrix, eval, evec, wspace):
    return gsl.gsl_eigen_hermv(matrix, eval, evec, wspace)

def gsl_matrix_complex_set(matrix, i, j, value):
    return gsl.gsl_matrix_complex_set(matrix, i, j, value)

def gsl_vector_get(vector, i):
    return gsl.gsl_vector_get(vector, i)

def gsl_matrix_complex_get(matrix, i, j):
    result = gsl_complex()
    gsl.gsl_matrix_complex_get(matrix, i, j, ctypes.byref(result))
    return result.dat[0], result.dat[1]

def compute_eigen(matrix_input, size):
    if not isinstance(matrix_input, list) or len(matrix_input) != size:
        raise ValueError("Input must be a square matrix of given size.")
    for row in matrix_input:
        if not isinstance(row, list) or len(row) != size:
            raise ValueError("Each row must have exactly 'size' elements.")

    # Initialize GSL structures
    matrix = gsl_matrix_complex_alloc(size, size)
    eval = gsl_vector_alloc(size)
    evec = gsl_matrix_complex_alloc(size, size)
    workspace = gsl_eigen_hermv_alloc(size)

    try:
        # Fill the matrix
        for i in range(size):
            for j in range(size):
                re, im = matrix_input[i][j]
                val = gsl_complex((ctypes.c_double * 2)(re, im))
                gsl_matrix_complex_set(matrix, i, j, val)

        # Compute eigenvalues and eigenvectors
        status = gsl_eigen_hermv(matrix, eval, evec, workspace)
        if status != 0:
            raise RuntimeError(f"GSL error during eigenvalue computation: {status}")

        # Extract eigenvalues
        eigenvalues = [gsl_vector_get(eval, i) for i in range(size)]

        # Extract eigenvectors
        eigenvectors = []
        for i in range(size):
            vec = [gsl_matrix_complex_get(evec, i, j) for j in range(size)]
            eigenvectors.append(vec)

        return eigenvalues, eigenvectors
    finally:
        # Free allocated memory
        gsl_matrix_complex_free(matrix)
        gsl_vector_free(eval)
        gsl_matrix_complex_free(evec)
        gsl_eigen_hermv_free(workspace)

