def gsl_vector_free(v):
    return gsl.gsl_vector_free(v)

def gsl_vector_set(v, i, x):
    return gsl.gsl_vector_set(v, ctypes.c_size_t(i), ctypes.c_double(x))

def gsl_vector_get(v, i):
    return gsl.gsl_vector_get(v, ctypes.c_size_t(i))

def gsl_wavelet_alloc(kind, t, n):
    return gsl.gsl_wavelet_alloc(kind, t, ctypes.c_size_t(n))

def gsl_wavelet_free(w):
    return gsl.gsl_wavelet_free(w)

def gsl_wavelet_workspace_alloc(n):
    return gsl.gsl_wavelet_workspace_alloc(ctypes.c_size_t(n))

def gsl_wavelet_workspace_free(w):
    return gsl.gsl_wavelet_workspace_free(w)

def gsl_wavelet_transform_forward(w, v, stride, n, wspace):
    return gsl.gsl_wavelet_transform_forward(
        w, 
        v, 
        ctypes.c_size_t(stride), 
        ctypes.c_size_t(n), 
        wspace
    )

def gsl_wavelet_transform_inverse(w, v, stride, n, wspace):
    return gsl.gsl_wavelet_transform_inverse(
        w, 
        v, 
        ctypes.c_size_t(stride), 
        ctypes.c_size_t(n), 
        wspace
    )

def read_data_from_file(file_path):
    with open(file_path, 'r') as f:
        data = [float(line.strip()) for line in f if line.strip()]
    return data

def main():
    file_path = input("Enter the file path: ")
    data = read_data_from_file(file_path)
    n = len(data)

    # Allocate vector
    v = gsl_vector_alloc(n)

    # Fill vector with data
    for i in range(n):
        gsl_vector_set(v, i, data[i])

    # Allocate wavelet and workspace
    w = gsl_wavelet_alloc(ctypes.c_int(0), ctypes.c_int(0), ctypes.c_size_t(n))
    wspace = gsl_wavelet_workspace_alloc(ctypes.c_size_t(n))

    # Forward transform
    gsl_wavelet_transform_forward(w, v, 1, n, wspace)

    # Zero out smallest coefficients (example thresholding)
    for i in range(n):
        val = gsl_vector_get(v, i)
        if abs(val) < 0.1:
            gsl_vector_set(v, i, 0.0)

    # Inverse transform
    gsl_wavelet_transform_inverse(w, v, 1, n, wspace)

    # Print original and transformed data
    print("Original\tTransformed")
    for i in range(n):
        print(f"{data[i]}\t{gsl_vector_get(v, i)}")

    # Free memory
    gsl_vector_free(v)
    gsl_wavelet_free(w)
    gsl_wavelet_workspace_free(wspace)

if __name__ == "__main__":
    main()

