#include <gsl/gsl_integration.h>

// Function to integrate: f(x) = x^m * exp(-x^2)
double f(double x, void *params) {
    int m = *(int*)params;
    return pow(x, m) * exp(-x*x);
}

// Integration function using GSL
void compute_integration(int m, int n, double *result) {
    gsl_integration_workspace *w = gsl_integration_workspace_alloc(n);
    double result_gsl, error;

    gsl_function F;
    F.function = &f;
    F.params = &m;

    gsl_integration_qags(&F, 0.0, 1.0, 0, 1e-7, n, w, &result_gsl, &error);

    *result = result_gsl;

    gsl_integration_workspace_free(w);
}

