    gsl_rng *r = gsl_rng_alloc(T);

    size_t n = 10000;
    double data[n];

    for (size_t i = 0; i < n; ++i) {
        data[i] = gsl_ran_rayleigh(r, 1.0);
    }

    gsl_rstat_workspace *w = gsl_rstat_alloc();
    for (size_t i = 0; i < n; ++i) {
        gsl_rstat_add(data[i], w);
    }

    double q025 = gsl_rstat_quantile(w, 0.25);
    double q050 = gsl_rstat_quantile(w, 0.50);
    double q075 = gsl_rstat_quantile(w, 0.75);

    qsort(data, n, sizeof(double), (int (*)(const void *, const void *)) &gsl_sort_double_cmp);

