void generate_rayleigh_data(double *data, size_t n, double sigma) {
    const gsl_rng_type *T;
    gsl_rng *r;

    gsl_rng_env_setup();
    T = gsl_rng_default;
    r = gsl_rng_alloc(T);

    for (size_t i = 0; i < n; ++i) {
        data[i] = gsl_ran_rayleigh(r, sigma);
    }

    gsl_rng_free(r);
}

void compute_quantiles(const double *data, size_t n, double quantiles[3]) {
    gsl_rstat_workspace *w = gsl_rstat_alloc(n);

    for (size_t i = 0; i < n; ++i) {
        gsl_rstat_add(w, data[i]);
    }

    quantiles[0] = gsl_rstat_quantile(w, 0.25);
    quantiles[1] = gsl_rstat_quantile(w, 0.50);
    quantiles[2] = gsl_rstat_quantile(w, 0.75);

    gsl_rstat_free(w);
}

int main() {
    size_t n = 10000;
    double sigma = 1.0;
    double data[n];
    double exact_quantiles[3];
    double estimated_quantiles[3];

    generate_rayleigh_data(data, n, sigma);

    // Compute exact quantiles by sorting the data
    qsort(data, n, sizeof(double), (int (*)(const void *, const void *)) &dcmp);
    exact_quantiles[0] = data[(int)(0.25 * n)];
    exact_quantiles[1] = data[(int)(0.50 * n)];
    exact_quantiles[2] = data[(int)(0.75 * n)];

    // Compute estimated quantiles using GSL running statistics workspace
    compute_quantiles(data, n, estimated_quantiles);

    // Calculate errors between exact and estimated quantiles
    double errors[3];
    for (int i = 0; i < 3; ++i) {
        errors[i] = fabs(exact_quantiles[i] - estimated_quantiles[i]);
    }

