import numpy as np

class GSLVector:
    def __init__(self, data):
        self.data = np.array(data, dtype=np.float64)
        self.size = len(self.data)
        self.libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define function prototypes
        self.gsl.gsl_vector_float_alloc.argtypes = [ctypes.c_size_t]
        self.gsl.gsl_vector_float_alloc.restype = ctypes.c_void_p

        self.gsl.gsl_vector_float_set.argtypes = [
            ctypes.c_void_p,  # gsl_vector_float *
            ctypes.c_size_t,  # size_t index
            ctypes.c_float   # float value
        ]
        self.gsl.gsl_vector_float_set.restype = None

        self.gsl.scaled_enorm.argtypes = [
            ctypes.c_void_p,  # gsl_vector_float *d
            ctypes.c_void_p   # gsl_vector_float *f
        ]
        self.gsl.scaled_enorm.restype = ctypes.c_double

        self.vector = self.create_gsl_vector()

    def create_gsl_vector(self):
        vector = self.gsl.gsl_vector_float_alloc(self.size)
        for i in range(self.size):
            self.gsl.gsl_vector_float_set(vector, i, self.data[i])
        return vector

    def scaled_enorm(self, other):
        if not isinstance(other, GSLVector):
            raise ValueError("Input must be an instance of GSLVector.")
        if self.size != other.size:
            raise ValueError("Vectors must have the same length.")
        return self.gsl.scaled_enorm(self.vector, other.vector)

