import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()
        self.gsl_type = ctypes.POINTER(ctypes.c_double) * rows
        for i in range(rows):
            self.gsl_type[i] = ctypes.pointer(self.data[i * cols])
        self.ptr = (ctypes.c_void_p * rows)()
        for i in range(rows):
            self.ptr[i] = ctypes.addressof(self.gsl_type[i].contents)

    def get_data(self):
        return [list(self.data[i * self.cols : (i + 1) * self.cols]) for i in range(self.rows)]

    def set_data(self, matrix):
        if len(matrix) != self.rows or any(len(row) != self.cols for row in matrix):
            raise ValueError("Matrix dimensions do not match.")
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = matrix[i][j]

# Load the libraries
gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define function prototypes
gsl gsl_linalg_exponential_ss.argtypes = [
    ctypes.POINTER(ctypes.c_void_p), 
    ctypes.POINTER(ctypes.c_void_p), 
    ctypes.c_int
]
gsl gsl_linalg_exponential_ss.restype = ctypes.c_int

def matrix_to_gsl(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    if any(len(row) != cols for row in matrix):
        raise ValueError("Input must be a square matrix.")
    gsl_matrix = GSLMatrix(rows, cols)
    gsl_matrix.set_data(matrix)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    data = gsl_matrix.get_data()
    return np.array(data)

def compute_matrix_exponential(matrix, mode):
    try:
        # Validate input matrix is square
        rows = len(matrix)
        cols = len(matrix[0])
        if any(len(row) != cols for row in matrix) or rows != cols:
            raise ValueError("Input must be a square matrix.")

        # Convert to GSL matrix
        A = matrix_to_gsl(matrix)
        result = GSLMatrix(rows, cols)

        # Prepare output matrix pointer
        out_ptr = (ctypes.c_void_p * rows)()
        for i in range(rows):
            out_ptr[i] = ctypes.addressof(result.gsl_type[i].contents)

        # Call GSL function
        status = gsl gsl_linalg_exponential_ss(
            (ctypes.c_void_p * rows)(*A.ptr), 
            out_ptr, 
            mode
        )
        if status != 0:
            raise RuntimeError(f"GSL error code: {status}")

        # Return result as 2D list
        return result.get_data()
    except Exception as e:
        print(f"Error computing matrix exponential: {e}")
        return None

