import ctypes
import math
from ctypes import c_double, CFUNCTYPE, POINTER

cdouble_func = CFUNCTYPE(c_double, c_double)

class GSLFunction:
    def __init__(self, py_func):
        self.py_func = py_func
        self.c_func = cdouble_func(self._wrapper)

    def _wrapper(self, x):
        return self.py_func(x)

    def get_c_func(self):
        return self.c_func

def test_func(x):
    return x ** 2

def sin_func(x):
    return math.sin(x)

def main():
    # Load the required libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define function and parameters for gsl_deriv_central
    gsl.gsl_deriv_central.argtypes = [cdouble_func, c_double, c_double, POINTER(c_double), POINTER(c_double)]
    gsl.gsl_deriv_central.restype = ctypes.c_int

    # Input values
    func_to_diff = test_func  # Change to sin_func or any other Python callable
    x = 1.0
    h = 1e-6

    # Wrap the Python function into a C-compatible function
    gsl_func = GSLFunction(func_to_diff).get_c_func()

    # Prepare output variables
    result = ctypes.c_double(0.0)
    error = ctypes.c_double(0.0)

    # Call the GSL derivative function
    status = gsl.gsl_deriv_central(gsl_func, x, h, ctypes.byref(result), ctypes.byref(error))

    if status == 0:
        print(f"Derivative: {result.value}, Error estimate: {error.value}")
    else:
        print("Error in computing derivative.")

if __name__ == "__main__":
    main()

