        gsl.gsl_matrix_alloc.argtypes = [ctypes.c_size_t, ctypes.c_size_t]
        gsl.gsl_matrix_alloc.restype = ctypes.c_void_p

        gsl.gsl_matrix_set.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_size_t, ctypes.c_double]
        gsl.gsl_matrix_get.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_size_t]
        gsl.gsl_matrix_get.restype = ctypes.c_double

        gsl.gsl_matrix_free.argtypes = [ctypes.c_void_p]

        # Allocate a 2x2 matrix
        self._gsl_matrix_p = gsl.gsl_matrix_alloc(2, 2)

    def set_element(self, i, j, value):
        gsl.gsl_matrix_set(self._gsl_matrix_p, i, j, ctypes.c_double(value))

    def get_element(self, i, j):
        return gsl.gsl_matrix_get(self._gsl_matrix_p, i, j)

    def to_dict(self):
        matrix_data = [[0.0 for _ in range(2)] for _ in range(2)]
        for i in range(2):
            for j in range(2):
                matrix_data[i][j] = self.get_element(i, j)
