def compute_weighted_absolute_deviation(w, wstride, data, stride, n):
    # Load the required GSL libraries in the correct order
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load GSL library: {e}")

    # Define argument and return types for the GSL function
    gsl.gsl_stats_wabsdev.argtypes = [
        ctypes.POINTER(ctypes.c_double),  # const double *w
        ctypes.c_int,                     # size_t wstride
        ctypes.POINTER(ctypes.c_double),  # const double *data
        ctypes.c_int,                     # size_t stride
        ctypes.c_int                      # size_t n
    ]
    gsl.gsl_stats_wabsdev.restype = ctypes.c_double

    # Convert Python lists to C-compatible arrays
    try:
        c_w = (ctypes.c_double * len(w))(*w)
        c_data = (ctypes.c_double * len(data))(*data)
    except TypeError:
        raise ValueError("Input arrays must contain numeric values.")

    # Validate input parameters
    if not isinstance(wstride, int) or not isinstance(stride, int) or not isinstance(n, int):
        raise TypeError("Stride and n must be integers.")
    if n <= 0:
        raise ValueError("Number of elements (n) must be positive.")
    if len(w) < abs(wstride) * (n - 1) + 1:
        raise ValueError("Weight array is too small for the given wstride and n.")
    if len(data) < abs(stride) * (n - 1) + 1:
        raise ValueError("Data array is too small for the given stride and n.")

    # Call the GSL function
    result = gsl.gsl_stats_wabsdev(c_w, wstride, c_data, stride, n)
    return float(result)

