gsl.gsl_ringbuf_size.argtypes = [ctypes.POINTER(RingBuf)]
gsl.gsl_ringbuf_size.restype = ctypes.c_size_t

gsl.gsl_ringbuf_free.argtypes = [ctypes.POINTER(RingBuf)]

class RingBuffer:
    def __init__(self, size):
        self.buf = gsl.gsl_ringbuf_alloc(size)
        if not self.buf:
            raise RuntimeError("Failed to allocate ring buffer")

    def insert(self, values):
        c_values = (ctypes.c_double * len(values))(*values)
        result = gsl.gsl_ringbuf_insert(self.buf, c_values, len(values))
        if result != 0:
            raise RuntimeError("Failed to insert into ring buffer")

    def to_list(self):
        data_ptr = gsl.gsl_ringbuf_data(self.buf)
        size = gsl.gsl_ringbuf_size(self.buf)
        return [data_ptr[i] for i in range(size)]

    def free(self):
        gsl.gsl_ringbuf_free(self.buf)

