        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define the gsl_matrix structure and functions
        class gsl_matrix(ctypes.Structure):
            _fields_ = [
                ('size1', ctypes.c_size_t),
                ('size2', ctypes.c_size_t),
                ('tda', ctypes.c_size_t),
                ('data', ctypes.POINTER(ctypes.c_double)),
                ('block', ctypes.c_void_p),
                ('owner', ctypes.c_int)
            ]

        self.gsl_matrix_type = gsl_matrix

        # Create a gsl_matrix from the numpy array
        self.gsl_matrix.contents = gsl_matrix(
            size1=self.n,
            size2=self.n,
            tda=self.n,
            data=self.matrix.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
            block=None,
            owner=0
        )

    def is_positive_definite(self):
        # Check if the matrix is symmetric
        for i in range(self.n):
            for j in range(i + 1, self.n):
                if abs(self.matrix[i][j] - self.matrix[j][i]) > 1e-10:
                    return False

        # Check if all eigenvalues are positive using numpy
        eigenvalues = np.linalg.eigvalsh(self.matrix)
        return all(eigenvalue > 1e-10 for eigenvalue in eigenvalues)

    def cholesky_decomp(self):
        if not self.is_positive_definite():
            raise ValueError('The input matrix is not positive definite.')

        # Call the GSL Cholesky decomposition function
        self.gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(self.gsl_matrix_type)]
        self.gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

        result = self.gsl.gsl_linalg_cholesky_decomp(ctypes.pointer(self.gsl_matrix.contents))
        if result != 0:
            raise RuntimeError('Cholesky decomposition failed.')

        # Convert the lower triangular matrix to a 2D list
        lower_triangular = [[0.0 for _ in range(self.n)] for _ in range(self.n)]
        for i in range(self.n):
            for j in range(i + 1):
                lower_triangular[i][j] = self.matrix[i][j]

        return lower_triangular

