import numpy as np

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return True
    except Exception as e:
        print(f"Error loading GSL libraries: {e}")
        return False

def cblas_zdscal(N, alpha, X, incX):
    if not isinstance(N, int) or N < 0:
        raise ValueError("N must be a non-negative integer.")
    if not isinstance(alpha, float):
        raise ValueError("alpha must be a float.")
    if not isinstance(X, list) or any(not isinstance(x, complex) for x in X):
        raise ValueError("X must be a list of complex numbers.")
    if not isinstance(incX, int) or incX <= 0:
        raise ValueError("incX must be a positive integer.")

    # Convert the Python list to a NumPy array of complex128 (double-precision complex)
    X_np = np.array(X, dtype=np.complex128, copy=False, order='C')

    # Get the function from the library
    cblas_zdscal_func = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so").cblas_zdscal

    # Define the argument and return types
    cblas_zdscal_func.argtypes = [
        ctypes.c_int,         # N
        ctypes.c_double,      # alpha
        ctypes.POINTER(ctypes.c_double),  # Real part of X
        ctypes.c_int          # incX
    ]

    # Extract real and imaginary parts into separate arrays
    X_real = X_np.real.astype(np.float64)
    X_imag = X_np.imag.astype(np.float64)

    # Call cblas_zdscal on both real and imaginary parts
    cblas_zdscal_func(N, alpha, X_real.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), incX)
    cblas_zdscal_func(N, alpha, X_imag.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), incX)

    # Combine back into a complex array
    scaled_X = X_real + 1j * X_imag

    # Return as a list of complex numbers
    return scaled_X.tolist()

