        # Define function prototypes for type checking and error handling
        self.gsl.gsl_rstat_quantile_alloc.argtypes = [ctypes.c_int]
        self.gsl.gsl_rstat_quantile_alloc.restype = ctypes.c_void_p

        self.gsl.gsl_rstat_quantile_reset.argtypes = [ctypes.c_void_p]
        self.gsl.gsl_rstat_quantile_reset.restype = None

        self.gsl.gsl_rstat_quantile_add.argtypes = [
            ctypes.c_void_p,
            ctypes.c_double
        ]
        self.gsl.gsl_rstat_quantile_add.restype = None

        self.gsl.gsl_rstat_quantile_get.argtypes = [
            ctypes.c_void_p,
            ctypes.c_double
        ]
        self.gsl.gsl_rstat_quantile_get.restype = ctypes.c_double

        self.gsl.gsl_rstat_quantile_free.argtypes = [ctypes.c_void_p]
        self.gsl.gsl_rstat_quantile_free.restype = None

        # Allocate workspace (default size is 1000, adjust if needed)
        self.workspace = self.gsl.gsl_rstat_quantile_alloc(1000)
        if not self.workspace:
            raise MemoryError("Failed to allocate GSL quantile workspace.")

    def __del__(self):
        # Free allocated memory when object is destroyed
        if hasattr(self, 'workspace') and self.workspace:
            self.gsl.gsl_rstat_quantile_free(self.workspace)

    def reset(self):
        self.gsl.gsl_rstat_quantile_reset(self.workspace)

    def add_values(self, values):
        for val in values:
            self.gsl.gsl_rstat_quantile_add(self.workspace, ctypes.c_double(val))

    def get_quantile(self, p):
        if not (0 <= p <= 1):
            raise ValueError("Quantile p must be between 0 and 1.")
        return self.gsl.gsl_rstat_quantile_get(self.workspace, ctypes.c_double(p))

